<?php
if (!defined('ABSPATH')) { exit; }

/** Focused management screens share the new portal and never render the legacy panel. */
trait SN_MIS_Management {
    private function sn_mis_management_page(string $page,array $input): void {
        if(!current_user_can('manage_options')) { echo '<p class="sn-mis-notice">این بخش برای مدیرکل است.</p>';return; }
        $tabs=['cases'=>'پرونده‌ها','plans'=>'برنامه توزیع','rules'=>'قواعد توزیع','branches'=>'شعبه‌ها','health'=>'سلامت سامانه','logs'=>'لاگ و عیب‌یابی'];
        echo '<nav class="sn-mis-subnav" aria-label="مدیریت MIS">';foreach($tabs as $key=>$label)echo '<a href="'.esc_url($this->sn_mis_v2_url($key)).'" '.($key===$page?'aria-current="page"':'').'>'.$label.'</a>';echo '</nav>';
        $this->sn_mis_management_feedback($page);
        if($page==='cases')$this->sn_mis_cases_page($input);
        elseif($page==='plans')$this->sn_mis_plans_page($input);
        elseif($page==='rules')$this->sn_mis_rules_page();
        elseif($page==='branches')$this->sn_mis_branches_page();
        elseif($page==='logs')$this->sn_mis_logs_page($input);
        else $this->sn_mis_health_page();
    }
    private function sn_mis_admin_form(string $action): void {
        echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'" class="sn-mis-form"><input type="hidden" name="action" value="sn_mis_'.$action.'">';$this->sn_mis_nonce_field('sn_mis_'.$action);
    }
    private function sn_mis_management_feedback(string $page): void {
        $r=get_option('sn_mis_last_report',[]);if(!is_array($r) || empty($r['action']) || !in_array($page,['plans','rules'],true))return;
        $action=(string)$r['action'];$labels=['distribution_rule_created'=>'قاعده توزیع ذخیره شد','distribution_plan_dry_run'=>'پیش‌نمایش برنامه توزیع','distribution_plan_created'=>'برنامه توزیع ساخته شد','distribution_plan_approve'=>'نتیجه تأیید برنامه','live_lead_creation_dry_run'=>'پیش‌نمایش ایجاد لید','live_leads_created_from_mis_plan'=>'نتیجه ایجاد لید','lead_pool_prepare_apply'=>'مخزن آماده توزیع به‌روزرسانی شد','lead_pool_prepare_dry_run'=>'پیش‌نمایش آماده‌سازی مخزن'];
        if(!isset($labels[$action]))return;
        $errors=(array)($r['errors']??[]);echo '<section class="sn-mis-notice '.($errors?'is-error':'').'" role="status"><strong>'.esc_html($labels[$action]).'</strong>';
        foreach(['created_items'=>'ردیف برنامه ساخته‌شده','created'=>'ایجادشده','planned_rows'=>'شماره در این برنامه','eligible_to_create'=>'آماده ایجاد در این مرحله','already_created'=>'قبلاً ایجادشده','blocked'=>'مسدود','active_plan_pool_rows'=>'رزرو در برنامه‌های فعال'] as $key=>$label)if(isset($r[$key]))echo '<span class="sn-mis-result-chip">'.$label.': '.number_format_i18n((int)$r[$key]).'</span>';
        foreach($errors as $error)echo '<p>'.esc_html($this->sn_mis_management_error((string)$error)).'</p>';
        if(!empty($r['created_plan_id']))echo '<a class="sn-btn" href="'.esc_url($this->sn_mis_v2_url('plans',['plan_id'=>(int)$r['created_plan_id']])).'">بازکردن برنامه ساخته‌شده</a>';
        $preview=$r['preview_rows']??$r['preview_items']??$r['candidates']??[];
        if($preview) { echo '<details><summary>دیدن شماره‌های بررسی‌شده؛ حداکثر ۲۰ نمونه</summary><div class="sn-mis-table-scroll"><table><thead><tr><th>شماره</th><th>فروشنده</th><th>نتیجه</th><th>دلیل</th></tr></thead><tbody>';foreach(array_slice($preview,0,20) as $row)echo '<tr><td><bdi>'.esc_html($row['phone']??'').'</bdi></td><td>'.esc_html($row['seller']??$row['manager']??'—').'</td><td>'.esc_html($this->sn_mis_management_error((string)($row['status']??''))).'</td><td>'.esc_html($this->sn_mis_management_error((string)($row['reason']??$row['skip_reason']??''))).'</td></tr>';echo '</tbody></table></div></details>'; }
        echo '</section>';
    }
    private function sn_mis_management_error(string $error): string {
        return ['manual_requires_one_seller'=>'برای تخصیص مستقیم دقیقاً یک فروشنده انتخاب کنید.','missing_seller'=>'فروشنده مشخص نیست.','duplicate_in_leads'=>'این شماره لید دارد.','missing_phone'=>'شماره معتبر نیست.','eligible'=>'مجاز در بررسی اولیه','blocked'=>'مسدود','confirmation_required'=>'تأیید نهایی عملیات انتخاب نشده است.','manager_must_have_sales_manager_position'=>'یک مدیر فروش فعال انتخاب کنید.','seller_selection_required'=>'حداقل یک فروشنده زیرمجموعه مدیر انتخاب کنید.','draft_rule_required'=>'یک قاعده آماده توزیع انتخاب کنید.','rule_manager_mismatch'=>'مدیر قاعده با مدیر انتخابی یکسان نیست.','plan_must_be_approved'=>'ابتدا برنامه را تأیید کنید.','plan_not_found'=>'برنامه پیدا نشد.','plan_status_not_approvable'=>'این برنامه قبلاً تأیید یا بسته شده است.','mis_distribution_tables_missing'=>'ساختار برنامه توزیع کامل نیست.','source_reserved_consumed_or_out_of_scope'=>'شماره مصرف، رزرو یا از محدوده برنامه خارج شده است.'][$error]??$error;
    }
    private function sn_mis_batch_status(string $status): string {
        return ['draft'=>'در انتظار فایل','imported'=>'آماده تخصیص','assigned_to_manager'=>'دارای تخصیص','archived'=>'بایگانی','deleted'=>'بسته‌شده','file_deleted'=>'بسته‌شده','reset_deleted'=>'بسته‌شده'][$status]??'نیازمند بررسی';
    }
    private function sn_mis_cases_page(array $input): void {
        global $wpdb;$service=$this->sn_mis_v2_service();$id=absint($input['case_id']??$input['sn_mis_batch_id']??0);
        if($id) {
            $batch=$service->rows($wpdb->prepare('SELECT * FROM '.$wpdb->prefix.'sn_mis_import_batches WHERE id=%d',$id));if(!$batch)throw new RuntimeException('پرونده پیدا نشد.');$b=$batch[0];
            echo '<section class="sn-mis-card"><div class="sn-mis-section-heading"><div><span class="sn-mis-eyebrow">'.esc_html($b['batch_code']).'</span><h3>'.esc_html($b['title']).'</h3><p>'.esc_html($this->sn_mis_batch_status($b['import_status'])).' · کمپین '.esc_html($b['campaign_code']?:'—').'</p></div><a class="sn-btn" href="'.esc_url($this->sn_mis_v2_url('cases')).'">همه پرونده‌ها</a></div><div class="sn-mis-metrics">';
            foreach(['total_rows'=>'ثبت‌شده','valid_rows'=>'معتبر هنگام ورود','invalid_rows'=>'نامعتبر','duplicate_rows'=>'تکراری'] as $key=>$label)echo '<article><strong>'.number_format_i18n((int)($b[$key]??0)).'</strong><span>'.$label.'</span></article>';echo '</div><div class="sn-mis-actions">';
            foreach(['upload'=>'ورود فایل و تخصیص','reports'=>'گزارش شماره‌ها','return'=>'بررسی بازگشت'] as $page=>$label)echo '<a class="sn-btn" href="'.esc_url($this->sn_mis_v2_url($page,['batch_id'=>$id])).'">'.$label.'</a>';echo '</div></section>';
            echo '<p><a class="sn-btn" href="'.esc_url($this->sn_mis_v2_url('plans',['section'=>'new','batch_id'=>$id,'manager_id'=>(int)($b['assigned_manager_user_id']??0)])).'">برنامه توزیع برای این پرونده</a></p>';
            $offset=absint($input['sn_mis_offset']??0);$r=$service->query(['batch_id'=>$id,'__projection_only'=>true],25,$offset);echo '<section class="sn-mis-card"><h3>شماره‌های این پرونده</h3>';$this->sn_mis_v2_table($r['rows']);$this->sn_mis_management_pager($r['total'],$offset,'cases',['case_id'=>$id],25);echo '</section>';
            if(!in_array($b['import_status'],['archived','deleted','file_deleted','reset_deleted'],true)) { echo '<details class="sn-mis-card"><summary>بایگانی پرونده با حفظ سوابق</summary><p>پرونده از جریان ورود و تخصیص جدید کنار گذاشته می‌شود. شماره‌ها و سوابق حذف نمی‌شوند.</p>';$this->sn_mis_v2_form_start('archive_batch');echo '<input type="hidden" name="batch_id" value="'.$id.'"><label>دلیل بایگانی<textarea name="reason" required></textarea></label><label><input type="checkbox" name="confirm" value="ARCHIVE" required>بایگانی با حفظ همه سوابق را تأیید می‌کنم.</label><button class="sn-btn">بایگانی پرونده</button></form></details>'; }
            return;
        }
        $search=sanitize_text_field($input['search']??'');$offset=absint($input['sn_mis_offset']??0);$where=' WHERE 1=1';if($search!=='') { $like='%'.$wpdb->esc_like($search).'%';$where.=$wpdb->prepare(' AND (batch_code LIKE %s OR title LIKE %s OR campaign_code LIKE %s)',$like,$like,$like); }
        $total=(int)$service->value('SELECT COUNT(*) FROM '.$wpdb->prefix.'sn_mis_import_batches'.$where);$rows=$service->rows('SELECT id,batch_code,title,campaign_code,total_rows,import_status,created_at FROM '.$wpdb->prefix.'sn_mis_import_batches'.$where.$wpdb->prepare(' ORDER BY id DESC LIMIT 20 OFFSET %d',$offset));
        echo '<section class="sn-mis-card"><div class="sn-mis-section-heading"><div><h3>پرونده‌ها</h3><p>پرونده را پیدا کنید؛ هر کار از صفحه همان پرونده ادامه پیدا می‌کند.</p></div><a class="sn-btn sn-btn-primary" href="'.esc_url($this->sn_mis_v2_url('upload')).'">ورود فایل جدید</a></div><form method="get" class="sn-mis-inline-search"><input type="hidden" name="sn_mis_page" value="cases"><label>جست‌وجوی پرونده<input type="search" name="search" value="'.esc_attr($search).'" placeholder="عنوان، کد پرونده یا کمپین"></label><button class="sn-btn">جست‌وجو</button></form><div class="sn-mis-table-scroll"><table><thead><tr><th>پرونده</th><th>کمپین</th><th>تعداد ثبت‌شده</th><th>وضعیت</th><th>اقدام</th></tr></thead><tbody>';
        foreach($rows as $r)echo '<tr><td><strong>'.esc_html($r['title']).'</strong><small>'.esc_html($r['batch_code']).'</small></td><td>'.esc_html($r['campaign_code']?:'—').'</td><td>'.number_format_i18n((int)$r['total_rows']).'</td><td><span class="sn-mis-badge">'.esc_html($this->sn_mis_batch_status($r['import_status'])).'</span></td><td><a class="sn-mis-text-action" href="'.esc_url($this->sn_mis_v2_url('cases',['case_id'=>(int)$r['id']])).'">مشاهده پرونده ←</a></td></tr>';
        if(!$rows)echo '<tr><td colspan="5" class="sn-mis-empty">پرونده‌ای با این جست‌وجو پیدا نشد.</td></tr>';echo '</tbody></table></div>';$this->sn_mis_management_pager($total,$offset,'cases',['search'=>$search],20);echo '</section>';
    }
    private function sn_mis_management_pager(int $total,int $offset,string $page,array $args,int $size=20): void {
        echo '<div class="sn-mis-pager"><span>'.number_format_i18n($total).' نتیجه · صفحه '.number_format_i18n((int)floor($offset/$size)+1).'</span>';if($offset>0)echo '<a href="'.esc_url($this->sn_mis_v2_url($page,$args+['sn_mis_offset'=>max(0,$offset-$size)])).'">قبلی</a>';if($offset+$size<$total)echo '<a href="'.esc_url($this->sn_mis_v2_url($page,$args+['sn_mis_offset'=>$offset+$size])).'">بعدی</a>';echo '</div>';
    }
    private function sn_mis_pool_page(array $input): void {
        global $wpdb;$service=$this->sn_mis_v2_service();$batch=absint($input['batch_id']??0);$manager=absint($input['manager_id']??0);$offset=absint($input['sn_mis_offset']??0);
        echo '<section class="sn-mis-card"><div class="sn-mis-section-heading"><div><h3>مخزن و تحویل به فروش</h3><p>شماره‌های آماده را ببینید و هر بار یک بخش کوچک را به مدیر تحویل دهید.</p></div><a class="sn-btn" href="'.esc_url($this->sn_mis_v2_url('plans')).'">برنامه‌های توزیع</a></div><form method="get" class="sn-mis-form"><input type="hidden" name="sn_mis_page" value="plans"><input type="hidden" name="section" value="pool">';$this->sn_mis_manager_select('manager_id',$manager);$this->sn_mis_case_select($input,$batch);echo '<button class="sn-btn">جست‌وجو و نمایش مخزن</button></form></section>';
        if(!$batch || !$manager)return;
        $total=(int)$service->value($wpdb->prepare('SELECT COUNT(*) FROM '.$wpdb->prefix.'sn_mis_lead_pool WHERE batch_id=%d AND assigned_manager_user_id=%d',$batch,$manager));$rows=$service->rows($wpdb->prepare('SELECT id,source_row_id,customer_name,normalized_phone,pool_status,assigned_seller_user_id FROM '.$wpdb->prefix.'sn_mis_lead_pool WHERE batch_id=%d AND assigned_manager_user_id=%d ORDER BY id DESC LIMIT 25 OFFSET %d',$batch,$manager,$offset));
        $report=get_option('sn_distribution_delivery_report',[]);if(is_array($report) && (int)($report['batch_id']??0)===$batch) { echo '<p role="status" class="sn-mis-notice">نتیجه آخرین تحویل: '.(int)($report['created']??0).' ایجادشده؛ '.(int)($report['duplicate_blocked']??0).' تکراری مسدود شد.';foreach($report['errors']??[] as $e)echo ' '.esc_html($this->sn_mis_management_error((string)$e));echo '</p>'; }
        echo '<section class="sn-mis-card"><h3>تحویل کنترل‌شده به مدیر</h3><p>حداکثر ۲۵ شماره در هر مرحله بررسی می‌شود. رزرو برنامه، مصرف یا مسیر توزیع موازی مانع تحویل دوباره است.</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'" class="sn-mis-form"><input type="hidden" name="action" value="sn_distribution_deliver_pool">';wp_nonce_field('sn_distribution_deliver_pool');echo '<input type="hidden" name="batch_id" value="'.$batch.'"><input type="hidden" name="manager_user_id" value="'.$manager.'"><label>دلیل تحویل<input name="reason" required></label><button name="run_mode" value="dry_run" class="sn-btn">پیش‌نمایش</button><label><input type="checkbox" name="confirm" value="APPLY">تحویل این مرحله را تأیید می‌کنم.</label><button name="run_mode" value="apply" class="sn-btn sn-btn-primary">تحویل به مدیر فروش</button></form></section><section class="sn-mis-card"><h3>شماره‌های مخزن</h3><div class="sn-mis-table-scroll"><table><thead><tr><th>شناسه</th><th>شماره / نام</th><th>وضعیت</th><th>فروشنده</th></tr></thead><tbody>';
        foreach($rows as $row)echo '<tr><td>#'.(int)$row['source_row_id'].'</td><td><bdi>'.esc_html($row['normalized_phone']).'</bdi><small>'.esc_html($row['customer_name']).'</small></td><td>'.esc_html(['ready'=>'در مخزن؛ نیازمند بررسی تحویل','consumed'=>'مصرف‌شده','returned_to_mis'=>'برگشتی'][$row['pool_status']]??'نیازمند بررسی').'</td><td>'.esc_html($row['assigned_seller_user_id']?$this->sn_user_label((int)$row['assigned_seller_user_id']):'—').'</td></tr>';if(!$rows)echo '<tr><td colspan="4" class="sn-mis-empty">شماره‌ای در مخزن این مدیر و پرونده نیست.</td></tr>';echo '</tbody></table></div>';$this->sn_mis_management_pager($total,$offset,'plans',['section'=>'pool','batch_id'=>$batch,'manager_id'=>$manager],25);echo '</section>';
    }
    private function sn_mis_rules_page(): void {
        $rules=$this->sn_mis_distribution_rules(50);echo '<section class="sn-mis-card"><h3>قاعده توزیع جدید</h3><p>روش تقسیم را مشخص کنید؛ ساخت برنامه و تأیید آن در مرحله بعد انجام می‌شود.</p>';$this->sn_mis_admin_form('create_distribution_rule');
        echo '<label>نام قاعده<input name="rule_name" maxlength="191" required placeholder="مثلاً سهم برابر تیم فروش"></label><label>روش تقسیم<select name="rule_type"><option value="equal_split">تقسیم برابر بین فروشندگان منتخب</option><option value="manual_selection">تخصیص به یک فروشنده منتخب</option></select></label>';$this->sn_mis_manager_select('manager_user_id',0,false);echo '<label>توضیح<textarea name="notes"></textarea></label><button class="sn-btn sn-btn-primary">ذخیره قاعده</button></form></section><section class="sn-mis-card"><h3>قواعد ثبت‌شده</h3><div class="sn-mis-table-scroll"><table><thead><tr><th>نام</th><th>روش</th><th>مدیر</th><th>اقدام</th></tr></thead><tbody>';
        foreach($rules as $r)echo '<tr><td>'.esc_html($r->rule_name).'</td><td>'.($r->rule_type==='equal_split'?'تقسیم برابر':'انتخاب مستقیم').'</td><td>'.esc_html($r->manager_user_id?$this->sn_user_label((int)$r->manager_user_id):'همه مدیران').'</td><td><a href="'.esc_url($this->sn_mis_v2_url('plans',['section'=>'new'])).'">ساخت برنامه</a></td></tr>';if(!$rules)echo '<tr><td colspan="4" class="sn-mis-empty">هنوز قاعده‌ای ثبت نشده است.</td></tr>';echo '</tbody></table></div><p class="sn-mis-muted">آخرین ۵۰ قاعده</p></section>';
    }
    private function sn_mis_case_select(array $input,int $selected): void {
        echo '<label>جست‌وجوی پرونده<input type="search" name="batch_search" value="'.esc_attr($input['batch_search']??'').'" placeholder="عنوان یا کد پرونده"></label><label>پرونده<select name="batch_id"><option value="">انتخاب پرونده</option>';
        foreach($this->sn_mis_batch_options($input+['batch_id'=>$selected],true) as $b)echo '<option value="'.(int)$b['id'].'" '.selected($selected,(int)$b['id'],false).'>'.esc_html($b['batch_code'].' — '.$b['title']).'</option>';echo '</select></label>';
    }
    private function sn_mis_manager_select(string $name,int $selected=0,bool $required=true): void {
        echo '<label>مدیر فروش<select name="'.esc_attr($name).'" '.($required?'required':'').'><option value="">'.($required?'انتخاب مدیر':'همه مدیران').'</option>';foreach($this->sn_mis_sales_managers() as $manager)echo '<option value="'.(int)$manager->user_id.'" '.selected($selected,(int)$manager->user_id,false).'>'.esc_html($this->sn_user_label((int)$manager->user_id)).'</option>';echo '</select></label>';
    }
    private function sn_mis_plans_page(array $input): void {
        global $wpdb;$service=$this->sn_mis_v2_service();$id=absint($input['plan_id']??$input['sn_mis_plan_id']??0);
        if($id) { $this->sn_mis_plan_detail($id,$input);return; }
        if(($input['section']??'')==='pool') { $this->sn_mis_pool_page($input);return; }
        $new=($input['section']??'')==='new';echo '<div class="sn-mis-section-heading"><div><h3>برنامه توزیع</h3><p>برنامه را بسازید، سهم‌ها را بررسی کنید و سپس تأیید کنید.</p></div><a class="sn-btn sn-btn-primary" href="'.esc_url($this->sn_mis_v2_url('plans',['section'=>'new'])).'">برنامه جدید</a><a class="sn-btn" href="'.esc_url($this->sn_mis_v2_url('plans',['section'=>'pool'])).'">مخزن و تحویل به فروش</a></div>';
        if($new) { $this->sn_mis_plan_editor($input);return; }
        $offset=absint($input['sn_mis_offset']??0);$total=(int)$service->value('SELECT COUNT(*) FROM '.$wpdb->prefix.'sn_mis_distribution_plans');$plans=$service->rows('SELECT p.id,p.plan_code,p.manager_user_id,p.plan_status,p.planned_rows,p.created_at,b.title batch_title FROM '.$wpdb->prefix.'sn_mis_distribution_plans p LEFT JOIN '.$wpdb->prefix.'sn_mis_import_batches b ON b.id=p.batch_id'.$wpdb->prepare(' ORDER BY p.id DESC LIMIT 20 OFFSET %d',$offset));
        echo '<section class="sn-mis-card"><div class="sn-mis-table-scroll"><table><thead><tr><th>برنامه / پرونده</th><th>مدیر</th><th>تعداد برنامه</th><th>وضعیت</th><th>اقدام</th></tr></thead><tbody>';foreach($plans as $p)echo '<tr><td><strong>'.esc_html($p['plan_code']).'</strong><small>'.esc_html($p['batch_title']??'').'</small></td><td>'.esc_html($this->sn_user_label((int)$p['manager_user_id'])).'</td><td>'.(int)$p['planned_rows'].'</td><td><span class="sn-mis-badge">'.esc_html($this->sn_mis_plan_status($p['plan_status'])).'</span></td><td><a href="'.esc_url($this->sn_mis_v2_url('plans',['plan_id'=>(int)$p['id']])).'">بررسی و ادامه ←</a></td></tr>';if(!$plans)echo '<tr><td colspan="5" class="sn-mis-empty">برنامه‌ای ثبت نشده است. با یک برنامه کوچک شروع کنید.</td></tr>';echo '</tbody></table></div>';$this->sn_mis_management_pager($total,$offset,'plans',[],20);echo '</section><section class="sn-mis-tip"><strong>کدام مسیر برای داده من است؟</strong><p>تخصیص‌های جدید از پنل مدیر فروش در زنجیره فروش ادامه پیدا می‌کنند. این برنامه‌ها برای داده‌های آماده مخزن و برنامه‌های قبلی نیز قابل استفاده‌اند.</p></section>';
    }
    private function sn_mis_plan_status(string $s): string { return ['draft'=>'پیش‌نویس','dry_run'=>'آماده بررسی','approved'=>'تأییدشده','completed'=>'تکمیل‌شده','cancelled'=>'لغوشده','archived'=>'بایگانی'][$s]??'نیازمند بررسی'; }
    private function sn_mis_plan_detail(int $id,array $input): void {
        global $wpdb;$service=$this->sn_mis_v2_service();$rows=$service->rows($wpdb->prepare('SELECT p.*,b.title batch_title FROM '.$wpdb->prefix.'sn_mis_distribution_plans p LEFT JOIN '.$wpdb->prefix.'sn_mis_import_batches b ON b.id=p.batch_id WHERE p.id=%d',$id));if(!$rows)throw new RuntimeException('برنامه پیدا نشد.');$p=$rows[0];
        $after=absint($input['after_id']??0);$totals=$service->rows($wpdb->prepare("SELECT COUNT(*) total,SUM(COALESCE(created_lead_id,0)>0) created,SUM(item_status='planned' AND COALESCE(created_lead_id,0)=0) pending,SUM(id>%d AND item_status='planned' AND COALESCE(created_lead_id,0)=0) remaining_after FROM {$wpdb->prefix}sn_mis_distribution_plan_items WHERE plan_id=%d",$after,$id))[0];
        echo '<section class="sn-mis-card"><div class="sn-mis-section-heading"><div><span class="sn-mis-eyebrow">'.esc_html($p['plan_code']).'</span><h3>'.esc_html($p['batch_title']?:'برنامه توزیع').'</h3><p>مدیر: '.esc_html($this->sn_user_label((int)$p['manager_user_id'])).'</p></div><span class="sn-mis-badge">'.esc_html($this->sn_mis_plan_status($p['plan_status'])).'</span></div><ol class="sn-mis-steps"><li>ساخت برنامه</li><li '.($p['plan_status']==='approved'?'class="is-complete"':'').'>تأیید سهم‌ها</li><li>ایجاد لید</li></ol><div class="sn-mis-metrics">';foreach(['total'=>'کل ردیف برنامه','created'=>'لید ایجادشده','pending'=>'منتظر بررسی نهایی'] as $key=>$label)echo '<article><strong>'.number_format_i18n((int)$totals[$key]).'</strong><span>'.$label.'</span></article>';echo '</div>';
        if(in_array($p['plan_status'],['draft','dry_run'],true)) { $this->sn_mis_admin_form('approve_distribution_plan');echo '<input type="hidden" name="plan_id" value="'.$id.'"><label>دلیل تأیید<input name="reason" required></label><label><input type="checkbox" name="confirm" value="APPROVE" required>سهم‌های جدول را بررسی و تأیید می‌کنم.</label><button class="sn-btn sn-btn-primary">تأیید برنامه</button></form>'; }
        elseif($p['plan_status']==='approved' && (int)$totals['remaining_after']>0) { echo '<p>در هر مرحله حداکثر ۲۵ شماره با کنترل وضعیت واقعی بررسی می‌شود.</p>';$this->sn_mis_admin_form('create_live_leads_from_plan');echo '<input type="hidden" name="plan_after" value="'.$after.'"><input type="hidden" name="plan_id" value="'.$id.'"><label>دلیل عملیات<input name="reason" required></label><button name="run_mode" value="dry_run" class="sn-btn">پیش‌نمایش این مرحله</button><label><input type="checkbox" name="confirm" value="APPLY">ایجاد لید برای شماره‌های مجاز این مرحله را تأیید می‌کنم.</label><button name="run_mode" value="apply" class="sn-btn sn-btn-primary">ایجاد لید؛ مرحله بعدی</button></form>'; }
        elseif((int)$totals['pending']>0)echo '<p class="sn-mis-notice">بررسی این دور تمام شد؛ '.(int)$totals['pending'].' شماره نیازمند تعیین تکلیف است. <a href="'.esc_url($this->sn_mis_v2_url('plans',['plan_id'=>$id])).'">بررسی دوباره از ابتدا</a></p>';
        elseif(!(int)$totals['pending'])echo '<p class="sn-mis-success">شماره‌ای در انتظار ایجاد لید باقی نمانده است.</p>';echo '</section>';
        $offset=absint($input['sn_mis_offset']??0);$items=$service->rows($wpdb->prepare('SELECT i.id,i.source_row_id,i.planned_seller_user_id,i.item_status,i.created_lead_id,i.skip_reason,p.normalized_phone,p.customer_phone FROM '.$wpdb->prefix.'sn_mis_distribution_plan_items i LEFT JOIN '.$wpdb->prefix.'sn_mis_lead_pool p ON p.id=i.pool_id WHERE i.plan_id=%d ORDER BY i.id LIMIT 25 OFFSET %d',$id,$offset));
        echo '<section class="sn-mis-card"><h3>سهم فروشندگان</h3><div class="sn-mis-table-scroll"><table><thead><tr><th>شناسه</th><th>شماره</th><th>فروشنده</th><th>وضعیت</th><th>لید</th></tr></thead><tbody>';foreach($items as $r)echo '<tr><td>#'.(int)$r['source_row_id'].'</td><td><bdi>'.esc_html($r['normalized_phone']?:$r['customer_phone']).'</bdi></td><td>'.esc_html($this->sn_user_label((int)$r['planned_seller_user_id'])).'</td><td>'.(!empty($r['created_lead_id'])?'ایجادشده':($r['item_status']==='planned'?'در انتظار بررسی':'کنار گذاشته‌شده')).'<small>'.esc_html($this->sn_mis_management_error((string)($r['skip_reason']??''))).'</small></td><td>'.(!empty($r['created_lead_id'])?'#'.(int)$r['created_lead_id']:'—').'</td></tr>';if(!$items)echo '<tr><td colspan="5" class="sn-mis-empty">ردیفی در این برنامه وجود ندارد.</td></tr>';echo '</tbody></table></div>';$this->sn_mis_management_pager((int)$totals['total'],$offset,'plans',['plan_id'=>$id],25);echo '</section>';
    }
    private function sn_mis_plan_editor(array $input): void {
        $manager=absint($input['manager_id']??0);$batch=absint($input['batch_id']??0);echo '<section class="sn-mis-card"><h3>۱. انتخاب مدیر و پرونده</h3><form method="get" class="sn-mis-form"><input type="hidden" name="sn_mis_page" value="plans"><input type="hidden" name="section" value="new">';$this->sn_mis_manager_select('manager_id',$manager);$this->sn_mis_case_select($input,$batch);echo '<button class="sn-btn">جست‌وجو و ادامه</button></form></section>';
        if(!$manager || !$batch)return;
        $sellers=$this->sn_mis_sellers_under_manager($manager);$rules=$this->sn_mis_distribution_rules(50);echo '<section class="sn-mis-card"><h3>۲. سهم‌بندی شماره‌های آماده</h3><p>برنامه جدید حداکثر ۱۰۰ شماره دارد؛ داده‌های مصرف‌شده یا رزروشده دوباره تخصیص نمی‌یابند.</p>';$this->sn_mis_admin_form('create_distribution_plan');echo '<input type="hidden" name="batch_id" value="'.$batch.'"><input type="hidden" name="manager_user_id" value="'.$manager.'"><label>قاعده<select name="rule_id" required><option value="">انتخاب قاعده</option>';foreach($rules as $r)if($r->status==='draft' && (!$r->manager_user_id || (int)$r->manager_user_id===$manager))echo '<option value="'.(int)$r->id.'">'.esc_html($r->rule_name).'</option>';echo '</select></label><label>تعداد در این برنامه<input type="number" name="plan_limit" min="1" max="100" value="100" required></label><fieldset><legend>فروشندگان این مدیر</legend>';foreach($sellers as $seller)echo '<label><input type="checkbox" name="seller_ids[]" value="'.(int)$seller.'">'.esc_html($this->sn_user_label((int)$seller)).'</label>';if(!$sellers)echo '<p>فروشنده فعالی در محدوده این مدیر پیدا نشد.</p>';echo '</fieldset><label>دلیل برنامه<textarea name="reason" required></textarea></label><button name="run_mode" value="dry_run" class="sn-btn">پیش‌نمایش سهم‌ها</button><label><input type="checkbox" name="confirm" value="APPLY">سهم‌بندی را بررسی کرده‌ام؛ برنامه پیش‌نویس ساخته شود.</label><button name="run_mode" value="apply" class="sn-btn sn-btn-primary">ساخت پیش‌نویس برنامه</button></form></section>';
        echo '<details class="sn-mis-card"><summary>شماره‌های قدیمی هنوز وارد مخزن آماده توزیع نشده‌اند؟</summary><p>این مرحله برای سوابق دارای مدیر و بدون مسیر توزیع موازی است. هر بار یک بخش کوچک آماده می‌شود.</p>';$this->sn_mis_admin_form('prepare_lead_pool');echo '<input type="hidden" name="batch_id" value="'.$batch.'"><input type="hidden" name="manager_user_id" value="'.$manager.'"><label>دلیل آماده‌سازی<input name="reason" required></label><button name="run_mode" value="dry_run" class="sn-btn">پیش‌نمایش</button><label><input type="checkbox" name="confirm" value="APPLY">آماده‌سازی مرحله‌ای را تأیید می‌کنم.</label><button name="run_mode" value="apply" class="sn-btn">آماده‌سازی این مرحله</button></form></details>';
    }
    private function sn_mis_branches_page(): void {
        echo '<section class="sn-mis-card"><h3>شعبه‌ها</h3><p>شعبه هنگام تخصیص ثبت می‌شود؛ تغییر نام‌های سازمانی، شعبه رویدادهای قدیمی را عوض نمی‌کند.</p><div class="sn-mis-branch-list">';foreach($this->sn_mis_v2_branches() as $label)echo '<span class="sn-mis-badge">'.esc_html($label).'</span>';echo '</div>';$this->sn_mis_v2_form_start('branches');echo '<label>نام شعبه جدید<input name="branch_label" maxlength="191" required></label><button class="sn-btn sn-btn-primary">افزودن شعبه</button></form></section>';
    }
    private function sn_mis_health_page(): void {
        global $wpdb;$dbok=(string)$wpdb->get_var('SELECT 1')==='1';$model=new SN_MIS_Read_Model($wpdb);$jobs=$this->sn_mis_jobs();
        echo '<section class="sn-mis-card"><h3>سلامت سامانه</h3><p>این بررسی فقط وضعیت اتصال و ساختار را می‌خواند؛ شماره‌ای را تغییر نمی‌دهد.</p><dl class="sn-mis-health-list">';
        foreach(['نسخه افزونه'=>SN_VERSION,'نسخه PHP'=>PHP_VERSION,'اتصال دیتابیس'=>$dbok?'برقرار':'نیازمند بررسی','پرتال MIS'=>$this->sn_mis_v2_service()->ready()?'آماده':'راه‌اندازی لازم','ابزارهای تکمیلی'=>$model->ready()&&$jobs->ready()?'آماده':'راه‌اندازی لازم','روش پردازش'=>'درخواست‌های کوتاه؛ مستقل از Cron'] as $key=>$value)echo '<div><dt>'.esc_html($key).'</dt><dd>'.esc_html($value).'</dd></div>';echo '</dl></section>';
        $this->sn_mis_setup_card();echo '<section class="sn-mis-tip"><strong>اگر پاسخ سرور طول می‌کشد</strong><p>از این نسخه، بازکردن تب‌ها و راه‌اندازی وب، تعمیر گسترده CRM یا ساخت ایندکس روی جدول‌های اصلی اجرا نمی‌کند. آدرس صفحه، زمان خطا و لاگ همان بازه برای تشخیص محدودیت‌های هاست لازم است.</p><a class="sn-btn" href="'.esc_url($this->sn_mis_v2_url('tools')).'">پردازش‌ها و بررسی آمار</a></section>';
    }
}
